import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        char[] p = br.readLine().trim().toCharArray();
        char[] a = br.readLine().trim().toCharArray();

        // A deve ter o mesmo comprimento de P
        if (p.length != a.length) {
            System.out.println('N');
            return;
        }

        int[] cnt = new int[26];
        for (char c : p) cnt[c - 'a']++;

        int stars = 0;
        for (char c : a) {
            if (c == '*') {
                stars++;
            } else {
                int idx = c - 'a';
                if (cnt[idx] == 0) {
                    System.out.println('N');
                    return;
                }
                cnt[idx]--;
            }
        }

        // A soma restante das contagens deve ser exatamente o número de '*'
        int rem = 0;
        for (int x : cnt) rem += x;

        System.out.println(rem == stars ? 'S' : 'N');
    }
}
